        return "Invalid ISBN characters"
    checksum = int(isbn[-1])
    isbn_digits = [int(digit) for digit in isbn[:-1]]
    sum_of_squares = 0
    for i, digit in enumerate(isbn_digits):
        sum_of_squares += (i + 1) * digit
    if sum_of_squares % 11 == 0:
        if checksum == 0:
            return "Right"
        else:
            isbn = isbn[:-1] + str(checksum)
            return isbn
    else:
        checksum = 11 - (sum_of_squares % 11)
        isbn = isbn[:-1] + str(checksum)
        return isbn

