def max_herb_value(T, M, herbs):
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    for i in range(M + 1):
        for j in range(T + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif herbs[i - 1][0] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - herbs[i - 1][0]] + herbs[i - 1][1])
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[M][T]

