def min_remaining_space(V, n, volumes):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = max(dp[i - 1], V - sum(volumes[:i]))
    return V - dp[-1]

def min_remaining_space(V, n, volumes):
    # Initialize a 2D array to store the maximum occupied volume for each item and each possible subset of items.
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Initialize the base case: the maximum occupied volume for the entire box is zero.
    for i in range(n + 1):
        dp[i][0] = 0

    # Loop through each item and each possible subset of items.
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # If the current item cannot be included in the current subset, skip it.
            if volumes[i - 1] > V:
                continue

            # Otherwise, consider including the current item in the current subset.
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + volumes[i - 1])

    # Return the difference between the total capacity of the box and the maximum occupied volume.
    return V - max(dp[n][j] for j in range(n + 1))

