def mod_inverse(a, b):
    if a >= b:
        return None
    p, q = a, b
    r, s = 0, 1
    while p > 0:
        t = q % p
        q, p = p, t
        r, s = s, r - q * s // p
    if r < 0:
        r += b
    return r

