def minimum_students_to_leave(heights):
    decreasing_heights = []
    increasing_heights = []
    for i in range(len(heights)):
        if i == 0:
            increasing_heights.append(heights[i])
        elif i == len(heights) - 1:
            decreasing_heights.append(heights[i])
        elif heights[i] > heights[i - 1] and heights[i] > heights[i + 1]:
            increasing_heights.append(heights[i])
        elif heights[i] < heights[i - 1] and heights[i] < heights[i + 1]:
            decreasing_heights.append(heights[i])
    return len(heights) - len(increasing_heights) - len(decreasing_heights)

