def min_groups(w, n, prices):
    dp = [[0] * (n+1) for _ in range(w+1)]
    for i in range(1, n+1):
        for j in range(1, w+1):
            if prices[i-1] > j:
                dp[j][i] = dp[j][i-1]
            else:
                dp[j][i] = max(dp[j][i-1], 1 + dp[j-prices[i-1]][i-1])
    return dp[w][n]

